-- GENERATED by db::migrations::tests::schema_snapshot_is_current.
-- Do not edit by hand: change db/migrations/, run cargo test, commit the diff.
-- Consumers: apps/mcp-server test fixtures seed their SQLite from this file.

CREATE TABLE _schema_version (
            version INTEGER PRIMARY KEY,
            applied_at TEXT NOT NULL DEFAULT (datetime('now'))
        );

CREATE TABLE agent_requests (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    kind TEXT NOT NULL CHECK (kind IN ('start_fix', 'run_scan')),
    project_id INTEGER NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
    env_url TEXT NOT NULL,
    check_id TEXT,
    scope TEXT CHECK (scope IS NULL OR scope IN ('web', 'code', 'full')),
    agent_tool TEXT NOT NULL,
    status TEXT NOT NULL DEFAULT 'requested'
        CHECK (status IN ('requested', 'running', 'fulfilled', 'failed', 'expired')),
    result_json TEXT,
    failure_detail TEXT,
    created_at INTEGER NOT NULL,
    updated_at INTEGER NOT NULL
, target_relative_path TEXT
    CHECK (target_relative_path IS NULL OR (kind = 'start_fix' AND length(target_relative_path) > 0)), target_line INTEGER
    CHECK (target_line IS NULL OR (
        target_relative_path IS NOT NULL AND typeof(target_line) = 'integer'
        AND target_line BETWEEN 1 AND 4294967295
    )));

CREATE TABLE alerts (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    project_id INTEGER NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
    env_url TEXT NOT NULL DEFAULT '',
    source TEXT NOT NULL,
    alert_id TEXT NOT NULL,
    severity TEXT NOT NULL,
    title TEXT NOT NULL,
    description TEXT NOT NULL,
    detail_json TEXT,
    occurred_at INTEGER NOT NULL,
    first_seen_at INTEGER NOT NULL,
    last_seen_at INTEGER NOT NULL,
    viewed_at INTEGER,
    dismissed_at INTEGER
);

CREATE TABLE causal_link_observations (
    project_id          INTEGER NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
    cause_check_id      TEXT NOT NULL,
    effect_check_id     TEXT NOT NULL,
    observed_at         INTEGER NOT NULL,
    co_active           INTEGER NOT NULL,
    co_resolved         INTEGER NOT NULL,
    resolution_event_id INTEGER,
    FOREIGN KEY (resolution_event_id) REFERENCES events(id) ON DELETE SET NULL
);

CREATE TABLE connected_group_revisions (
    project_id INTEGER NOT NULL,
    env_url TEXT NOT NULL,
    check_id TEXT NOT NULL,
    state_revision INTEGER NOT NULL CHECK (state_revision >= 0),
    pulled_at INTEGER NOT NULL,
    PRIMARY KEY (project_id, env_url, check_id),
    FOREIGN KEY (project_id, env_url)
        REFERENCES connected_sites(project_id, env_url) ON DELETE CASCADE
);

CREATE TABLE connected_mutation_outbox (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    project_id INTEGER NOT NULL,
    env_url TEXT NOT NULL,
    check_id TEXT NOT NULL,
    decision TEXT NOT NULL CHECK (
        decision IN ('reopen', 'snooze', 'ignore', 'block', 'claim_fixed')
    ),
    snooze_until INTEGER,
    block_reason TEXT,
    based_on_revision INTEGER NOT NULL CHECK (based_on_revision >= 0),
    idempotency_key TEXT NOT NULL UNIQUE CHECK (length(idempotency_key) > 0),
    decided_at INTEGER NOT NULL,
    conflicted_at INTEGER,
    conflict_state TEXT,
    conflict_revision INTEGER,
    UNIQUE (project_id, env_url, check_id),
    CHECK ((decision = 'snooze') = (snooze_until IS NOT NULL)),
    CHECK (block_reason IS NULL OR decision = 'block'),
    CHECK ((conflicted_at IS NULL) = (conflict_state IS NULL)),
    CHECK ((conflicted_at IS NULL) = (conflict_revision IS NULL)),
    FOREIGN KEY (project_id, env_url)
        REFERENCES connected_sites(project_id, env_url) ON DELETE CASCADE
);

CREATE TABLE connected_producer (
    id INTEGER PRIMARY KEY CHECK (id = 1),
    installation_id TEXT NOT NULL CHECK (length(installation_id) > 0),
    submission_sequence INTEGER NOT NULL CHECK (submission_sequence >= 0),
    minted_at INTEGER NOT NULL
);

CREATE TABLE connected_site_watermarks (
    project_id INTEGER NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
    env_url TEXT NOT NULL,
    event_sequence INTEGER NOT NULL CHECK (event_sequence >= 0),
    pulled_at INTEGER NOT NULL,
    PRIMARY KEY (project_id, env_url)
);

CREATE TABLE connected_sites (
    project_id INTEGER NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
    env_url TEXT NOT NULL,
    site_id TEXT NOT NULL CHECK (length(site_id) > 0),
    connected_at INTEGER NOT NULL,
    bootstrapped_at INTEGER, fingerprint_key_version INTEGER NOT NULL DEFAULT 1, pending_key_version INTEGER, scope_synced_revision INTEGER NOT NULL DEFAULT 0
    CHECK (scope_synced_revision >= 0),
    PRIMARY KEY (project_id, env_url)
);

CREATE TABLE cross_project_pattern_index (
    check_id        TEXT PRIMARY KEY,
    project_count   INTEGER NOT NULL,
    latest_seen_ms  INTEGER NOT NULL,
    updated_at      INTEGER NOT NULL
);

CREATE TABLE "dismissed_integration_hints" (
    project_id INTEGER NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
    check_id TEXT NOT NULL,
