    occurred_at_ms INTEGER NOT NULL,
    title TEXT NOT NULL,
    summary TEXT NOT NULL DEFAULT '',
    detail TEXT,
    source TEXT NOT NULL DEFAULT 'internal',
    source_id TEXT,
    metadata TEXT,
    UNIQUE(project_id, source, source_id)
);

CREATE TABLE fix_attempts (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    project_id INTEGER NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
    env_url TEXT NOT NULL,
    check_id TEXT NOT NULL,
    agent_tool TEXT NOT NULL,
    status TEXT NOT NULL DEFAULT 'briefed',
    brief_md TEXT NOT NULL DEFAULT '',
    agent_summary TEXT,
    failure_detail TEXT,
    verify_started_at INTEGER,
    created_at INTEGER NOT NULL,
    updated_at INTEGER NOT NULL,
    brief_fetched_at INTEGER
, target_kind TEXT NOT NULL DEFAULT 'group'
    CHECK(target_kind IN ('group', 'occurrence')), target_relative_path TEXT, target_line INTEGER, producer_rule TEXT, target_occurrence_count INTEGER);

