    project_id INTEGER NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
    site_url TEXT NOT NULL,
    period_days INTEGER NOT NULL,
    report_title TEXT NOT NULL DEFAULT 'Website Health Report',
    generated_at TEXT NOT NULL DEFAULT (datetime('now')),
    branding_json TEXT,
    sections_json TEXT,
    report_summary_json TEXT,
    output_format TEXT NOT NULL DEFAULT 'preview'
);

CREATE TABLE scan_executions (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    project_id INTEGER REFERENCES projects(id) ON DELETE SET NULL,
    environment_id INTEGER REFERENCES environments(id) ON DELETE SET NULL,
    environment_url TEXT,
    environment_scope_key TEXT NOT NULL,
    requested_mode TEXT NOT NULL
        CHECK (requested_mode IN ('full', 'web', 'code')),
    web_focus TEXT
        CHECK (web_focus IS NULL OR web_focus IN
            ('health', 'security', 'accessibility', 'polish')),
    trigger TEXT NOT NULL
        CHECK (trigger IN
            ('manual', 'tray', 'scheduled', 'verification', 'background', 'migration')),
    admission_class TEXT NOT NULL
        CHECK (admission_class IN
            ('general_scan', 'bounded_verification', 'system_exempt')),
    status TEXT NOT NULL DEFAULT 'planned'
        CHECK (status IN
            ('planned', 'running', 'complete', 'partial', 'failed', 'cancelled')),
    idempotency_key TEXT NOT NULL UNIQUE,
    request_fingerprint TEXT NOT NULL,
    started_at INTEGER NOT NULL,
    completed_at INTEGER,
    score_snapshot_id INTEGER REFERENCES score_snapshots(id) ON DELETE SET NULL,
    failure_summary TEXT,
    legacy_provenance TEXT,
    web_status TEXT
        CHECK (web_status IS NULL OR web_status IN
            ('planned', 'running', 'complete', 'failed', 'cancelled', 'skipped')),
    web_detail TEXT,
    code_status TEXT
        CHECK (code_status IS NULL OR code_status IN
            ('planned', 'running', 'complete', 'failed', 'cancelled', 'skipped')),
    code_detail TEXT
, based_on_event_sequence INTEGER NOT NULL DEFAULT 0);

CREATE TABLE scan_findings (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    run_id INTEGER NOT NULL REFERENCES scan_runs(id) ON DELETE CASCADE,
    ordinal INTEGER NOT NULL CHECK(ordinal >= 0),
    occurrence_id TEXT NOT NULL,
    source TEXT NOT NULL CHECK(source IN ('web_scan', 'code_scan')),
    canonical_check_id TEXT NOT NULL,
    producer_check_id TEXT NOT NULL,
    category TEXT NOT NULL,
    producer_category TEXT NOT NULL,
    domain TEXT,
    verdict TEXT NOT NULL CHECK(verdict IN ('pass', 'fail', 'warn', 'skipped')),
    severity TEXT NOT NULL CHECK(severity IN ('critical', 'high', 'medium', 'low')),
    confidence TEXT NOT NULL CHECK(confidence IN ('confirmed', 'high', 'needs_review')),
    confidence_reason TEXT,
    title TEXT NOT NULL,
    description TEXT NOT NULL,
    fix_prompt TEXT,
    producer_fix_prompt TEXT,
    manual_fix TEXT,
    why_it_matters TEXT,
    verification_hint TEXT,
    raw_data TEXT,
    detail_json TEXT,
    location_kind TEXT NOT NULL CHECK(location_kind IN
        ('page', 'file', 'project', 'site', 'none')),
    page_url TEXT,
    relative_path TEXT,
    line INTEGER,
    UNIQUE(run_id, ordinal),
    UNIQUE(run_id, occurrence_id)
);

CREATE TABLE scan_runs (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    execution_id INTEGER NOT NULL REFERENCES scan_executions(id) ON DELETE CASCADE,
    parent_run_id INTEGER REFERENCES scan_runs(id) ON DELETE CASCADE,
    project_id INTEGER REFERENCES projects(id) ON DELETE SET NULL,
    site_id INTEGER REFERENCES sites(id) ON DELETE SET NULL,
    environment_url TEXT,
    environment_scope_key TEXT NOT NULL,
    source TEXT NOT NULL CHECK(source IN ('web_scan', 'code_scan')),
    run_kind TEXT NOT NULL CHECK(run_kind IN ('single', 'multi_parent', 'page', 'code')),
    status TEXT NOT NULL CHECK(status IN
        ('planned', 'running', 'complete', 'failed', 'cancelled', 'skipped')),
    focus TEXT,
    started_at INTEGER NOT NULL,
    completed_at INTEGER,
    timestamp_text TEXT NOT NULL,
    raw_score INTEGER,
    duration_ms INTEGER NOT NULL DEFAULT 0,
    coverage_kind TEXT NOT NULL CHECK(coverage_kind IN
        ('site', 'page_set', 'page', 'project', 'check_set', 'rule_set')),
    coverage_json TEXT NOT NULL DEFAULT '{}',
    diagnostics_json TEXT,
    status_detail TEXT,
    detail_state TEXT NOT NULL DEFAULT 'exact'
        CHECK(detail_state IN ('exact', 'limited_legacy')),
    -- Web diagnostics.
    mode TEXT,
    security_score INTEGER,
    performance_score INTEGER,
    seo_score INTEGER,
    accessibility_score INTEGER,
    compliance_score INTEGER,
    config_score INTEGER,
    polish_score INTEGER,
    issues_total INTEGER NOT NULL DEFAULT 0,
    issues_critical INTEGER NOT NULL DEFAULT 0,
    issues_high INTEGER NOT NULL DEFAULT 0,
    issues_medium INTEGER NOT NULL DEFAULT 0,
    issues_low INTEGER NOT NULL DEFAULT 0,
    issues_passed INTEGER NOT NULL DEFAULT 0,
    detected_stack TEXT,
    page_url TEXT,
    total_pages INTEGER,
    completed_pages INTEGER,
    axe_enabled INTEGER,
    -- Code diagnostics.
    project_path TEXT,
    framework TEXT,
    -- Deterministic one-way-backfill provenance. New runs leave these NULL.
    legacy_source TEXT,
    legacy_id INTEGER, engine_release TEXT, manifest_digest TEXT, canonicalizer INTEGER, crawl_profile INTEGER, execution_profile_json TEXT, scope_revision INTEGER, code_commit_sha TEXT, code_tree_clean INTEGER
  CHECK (code_tree_clean IS NULL OR code_tree_clean IN (0, 1)),
    UNIQUE(legacy_source, legacy_id)
);

CREATE TABLE scan_schedules (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    project_id INTEGER NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
    environment_id INTEGER NOT NULL REFERENCES environments(id) ON DELETE CASCADE,
    frequency TEXT NOT NULL DEFAULT 'off' CHECK(frequency IN ('off', 'daily', 'weekly')),
    time_of_day TEXT NOT NULL DEFAULT '09:00',
    day_of_week INTEGER,
    -- Schedulable focuses (core::scanner::ScheduledScanType): the four web
    -- ScanType values, 'code' (routes to the Code Scan engine), and 'full'
    -- (a web scan plus a Code Scan, mirroring the manual runner).
    scan_type TEXT NOT NULL DEFAULT 'health' CHECK(scan_type IN ('health', 'security', 'accessibility', 'polish', 'code', 'full')),
    last_run_at TEXT,
    next_run_at TEXT,
    -- No now-based column defaults (guardrail: migrations after the baseline
    -- supply timestamps from Rust). Existing rows copy their values below; the
    -- only insert path, save_scan_schedule, sets created_at and updated_at.
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL,
    UNIQUE(project_id, environment_id, scan_type)
);

CREATE TABLE score_snapshots (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    project_id INTEGER NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
    -- Normalized environment URL ('' when scored without an environment),
    -- matching the env scoping of the work_items the score reads.
    environment_url TEXT NOT NULL DEFAULT '',
    overall REAL NOT NULL,
    critical_count INTEGER NOT NULL DEFAULT 0,
    high_count INTEGER NOT NULL DEFAULT 0,
    medium_count INTEGER NOT NULL DEFAULT 0,
    low_count INTEGER NOT NULL DEFAULT 0,
    exploitable_capped INTEGER NOT NULL DEFAULT 0,
    computed_at INTEGER NOT NULL
);

CREATE TABLE signal_baselines (
    project_id   INTEGER NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
    signal_key   TEXT NOT NULL,
