, scope_revision INTEGER NOT NULL DEFAULT 0, scope_updated_at TEXT, profile_revision INTEGER NOT NULL DEFAULT 0);

CREATE TABLE trial_state (
    id INTEGER PRIMARY KEY CHECK (id = 1),
